import {addBunkerEquipment,instanceStaticProps} from './bunker-equipment.js';
import * as THREE from './vendor/three.module.js';
import {fixtureBlocksNode,floorHeights} from './reference-geometry.js';

// Source furniture is presentation, with the original collision footprints retained.
export const FURNITURE_ENTITIES=[184,185,214,215,217,263,266,275,337];
const roomFloor=y=>y>=2.8?3.6:0;
export function supportHeight(data,x,z,originY){const floors=floorHeights(data,x,z).filter(h=>h<=originY+.08);return floors.length?Math.max(...floors):roomFloor(originY)}
export function occupiesWalkingSpace(bounds,nodes,pad=.40){return nodes.some(n=>n.x>bounds.min.x-pad&&n.x<bounds.max.x+pad&&n.z>bounds.min.z-pad&&n.z<bounds.max.z+pad&&n.y<bounds.max.y-.08&&n.y+1.8>bounds.min.y+.08)}

export function buildReferenceDressing(scene,assets,map,original){
 const data=map.reference.data,props=[],owned=[],contact=[],details=[],replaced=new Set(FURNITURE_ENTITIES),diagnostics={grounded:0,replacedFurniture:0,rejected:0,outdoorRejected:0};
 original.traverse(o=>{if(o.isMesh&&replaced.has(o.userData.sourceEntityId)){o.visible=false;o.layers.set(31);o.castShadow=false;o.userData.replacedFurniture=true}});
 function facing(x,z,y){let best,cost=Infinity;for(const p of data.nav.nodes){if(Math.abs(p.y-y)>.5)continue;const d=Math.hypot(p.x-x,p.z-z);if(d>.5&&d<cost){cost=d;best=p}}if(!best)return 0;const dx=best.x-x,dz=best.z-z;return Math.abs(dx)>Math.abs(dz)?Math.sign(dx)*Math.PI/2:dz<0?Math.PI:0}
 const decorativeNodes=data.nav.nodes.filter(n=>!(map.dressing?.colliders||[]).some(b=>fixtureBlocksNode(b,n)));
 function place(asset,x,y,z,{height,dimensions,rotation=0,sourceEntityId,sourceBrushId,role='scenery',testClearance=true,room,assemblyId,id,physical=false}={}){
  const object=assets.model(asset,{height,dimensions});object.position.set(x,y,z);object.rotation.y=rotation;object.userData.dressing={asset,sourceEntityId,sourceBrushId,role,supportY:y,room,assemblyId,id,physical};object.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(object);
  if(testClearance&&occupiesWalkingSpace(bounds,decorativeNodes,.35)){diagnostics.rejected++;return null}
  object.traverse(o=>{if(o.isMesh){o.castShadow=role==='source-cover'||role==='equipment-bay';o.receiveShadow=true;o.userData.dressingRole=role}});scene.add(object);props.push(object);diagnostics.grounded++;contact.push({x,y,z,w:bounds.max.x-bounds.min.x,d:bounds.max.z-bounds.min.z});return object;
 }
 for(const brush of data.brushes.filter(b=>replaced.has(b.entityId))){const [x0,by,z0]=brush.min,[x1,top,z1]=brush.max,w=x1-x0,d=z1-z0,base=Math.max(by,roomFloor(by)),h=top-base;if(h<.15||w<.25||d<.25)continue;const x=(x0+x1)/2,z=(z0+z1)/2,yaw=facing(x,z,base),sideways=Math.abs(Math.sin(yaw))>.5,asset=h>1.15?'lab-cabinet':h>.60?'lab-cabinet-low':'lab-cargo-case';
  place(asset,x,base,z,{dimensions:sideways?[d-.025,h,w-.025]:[w-.025,h,d-.025],rotation:yaw,role:'source-cover',sourceEntityId:brush.entityId,sourceBrushId:brush.id,testClearance:false});diagnostics.replacedFurniture++;
  if(h>.6&&h<1.15)place('lab-field-device-b',x,top,z,{height:.22,rotation:yaw,sourceEntityId:brush.entityId,sourceBrushId:brush.id,role:'equipment-detail'});
  if([184,214,217].includes(brush.entityId))place('lab-toolbox',x,top,z,{height:.22,rotation:yaw,sourceEntityId:brush.entityId,sourceBrushId:brush.id,role:'equipment-detail'});
 }
 const equipment=addBunkerEquipment(scene,assets,map,place);

 const steel=new THREE.MeshStandardMaterial({color:'#738890',roughness:.7,metalness:.25}),clamp=new THREE.MeshStandardMaterial({color:'#a2b1b3',roughness:.8}),housing=new THREE.MeshStandardMaterial({color:'#435861',roughness:.7}),warm=new THREE.MeshStandardMaterial({color:'#eee2c3',emissive:'#ffe0a9',emissiveIntensity:1.35}),cool=new THREE.MeshStandardMaterial({color:'#d4e6e2',emissive:'#c0e5e3',emissiveIntensity:1.1});owned.push(steel,clamp,housing,warm,cool);
 const cylinder=new THREE.CylinderGeometry(1,1,1,8),cube=new THREE.BoxGeometry(1,1,1);owned.push(cylinder,cube);const batches=new Map();
 function detail(geo,mat,position,scale,quaternion=new THREE.Quaternion(),role='wall-detail'){if(!batches.has(mat))batches.set(mat,[]);const t=new THREE.Object3D();t.position.copy(position);t.scale.set(...scale);t.quaternion.copy(quaternion);t.updateMatrix();batches.get(mat).push({geo,matrix:t.matrix.clone(),role})}
 function segment(a,b,radius,mat=steel){const d=b.clone().sub(a),q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());detail(cylinder,mat,a.clone().add(b).multiplyScalar(.5),[radius,d.length(),radius],q)}
 let runs=0;const walls=data.faces.filter(f=>f.visible&&f.material.toLowerCase().includes('wall')&&Math.abs(f.normal[1])<.01);
 for(const floor of [0,3.6]){let floorRuns=0;for(const f of walls){if(floorRuns>=12)break;const points=[];for(let i=0;i<f.vertices.length;i++){const a=f.vertices[i],b=f.vertices[(i+1)%f.vertices.length],y=floor+2.85;if((a[1]-y)*(b[1]-y)>=0||Math.abs(a[1]-b[1])<.001)continue;const t=(y-a[1])/(b[1]-a[1]);points.push(new THREE.Vector3(a[0]+(b[0]-a[0])*t,y,a[2]+(b[2]-a[2])*t))}if(points.length<2)continue;let a=points[0],b=points[1];const length=a.distanceTo(b),mid=a.clone().add(b).multiplyScalar(.5),n=new THREE.Vector3(...f.normal);if(length<2.7||length>14||mid.x<map.bounds.minX||mid.x>map.bounds.maxX||mid.z<map.bounds.minZ||mid.z>map.bounds.maxZ)continue;const front=mid.clone().addScaledVector(n,.9);if(!data.nav.nodes.some(p=>Math.abs(p.y-floor)<.3&&Math.hypot(p.x-front.x,p.z-front.z)<.8))continue;if((mid.x>2&&mid.x<5&&mid.z>4&&mid.z<13)||(mid.z<-15&&mid.x>-3&&mid.x<3))continue;const dir=b.clone().sub(a).normalize();a=a.clone().addScaledVector(dir,.3).addScaledVector(n,.055);b=b.clone().addScaledVector(dir,-.3).addScaledVector(n,.055);segment(a,b,.023);for(let t=.5;t<length-.4;t+=2){const p=a.clone().addScaledVector(dir,t);detail(cube,clamp,p,[.10,.10,.10])}runs++;floorRuns++}}
 for(const e of data.entities.filter(e=>e.properties.model?.toLowerCase().includes('/lamp_ndu')&&e.origin)){const p=new THREE.Vector3(...e.origin);if(p.x<map.bounds.minX||p.x>map.bounds.maxX||p.z<map.bounds.minZ||p.z>map.bounds.maxZ)continue;const y=roomFloor(p.y-2.2)+3.25;p.y=Math.min(p.y,y);detail(cube,housing,p,[.85,.10,.22]);detail(cube,p.x<5?warm:cool,p.clone().add(new THREE.Vector3(0,-.055,0)),[.67,.015,.15]);}
 for(const [mat,items]of batches){for(const geo of [cube,cylinder]){const subset=items.filter(i=>i.geo===geo);if(!subset.length)continue;const mesh=new THREE.InstancedMesh(geo,mat,subset.length);subset.forEach((item,i)=>mesh.setMatrixAt(i,item.matrix));mesh.userData.dressingRole='wall-detail';mesh.castShadow=false;mesh.receiveShadow=true;scene.add(mesh);details.push(mesh)}}
 // Contact shade sits on the existing surface; it has no collision or gameplay role.
 const shadowPixels=new Uint8Array(64*64*4);for(let z=0;z<64;z++)for(let x=0;x<64;x++){const r=Math.max(Math.abs((x-31.5)/32),Math.abs((z-31.5)/32)),a=Math.pow(Math.max(0,1-r),1.4);shadowPixels.set([18,30,33,Math.round(a*220)],(z*64+x)*4)}
 const shadowTexture=new THREE.DataTexture(shadowPixels,64,64,THREE.RGBAFormat);shadowTexture.colorSpace=THREE.SRGBColorSpace;shadowTexture.needsUpdate=true;shadowTexture.userData.reviewKind='contact-shade';const shadowMaterial=new THREE.MeshBasicMaterial({map:shadowTexture,transparent:true,opacity:.20,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1}),shadowGeometry=new THREE.PlaneGeometry(1,1);owned.push(shadowTexture,shadowMaterial,shadowGeometry);
 const pillars=data.brushes.filter(b=>b.solid&&!b.movable&&b.max[1]-b.min[1]>2&&b.max[0]-b.min[0]<1.3&&b.max[2]-b.min[2]<1.3&&b.max[0]-b.min[0]>.2&&b.max[2]-b.min[2]>.2).map(b=>({x:(b.min[0]+b.max[0])/2,z:(b.min[2]+b.max[2])/2,y:Math.max(b.min[1],roomFloor(b.min[1])),w:b.max[0]-b.min[0],d:b.max[2]-b.min[2]})),shadows=[...contact,...pillars].filter(p=>(Math.abs(p.y-roomFloor(p.y))<.12||(map.dressing?.surfaces||[]).some(s=>Math.abs(s.max[1]-p.y)<.05&&p.x>s.min[0]&&p.x<s.max[0]&&p.z>s.min[2]&&p.z<s.max[2]))&&p.x>map.bounds.minX&&p.x<map.bounds.maxX&&p.z>map.bounds.minZ&&p.z<map.bounds.maxZ),shadowBatch=new THREE.InstancedMesh(shadowGeometry,shadowMaterial,shadows.length),shadowTransform=new THREE.Object3D();
 shadows.forEach((p,i)=>{shadowTransform.position.set(p.x,p.y+.012,p.z);shadowTransform.rotation.x=-Math.PI/2;shadowTransform.scale.set(p.w+.65,p.d+.65,1);shadowTransform.updateMatrix();shadowBatch.setMatrixAt(i,shadowTransform.matrix)});shadowBatch.userData.dressingRole='contact-shade';shadowBatch.renderOrder=1;scene.add(shadowBatch);details.push(shadowBatch);
 const instancing=instanceStaticProps(scene,props);details.push(...equipment.details);
 return {props,details,contact,update:equipment.update,diagnostics:{...diagnostics,conduitRuns:runs,contactShadows:shadows.length,propInstances:instancing.instances,propBatches:instancing.batches.length,equipmentBays:map.dressing.bays.length},dispose(){equipment.dispose();instancing.dispose();for(const r of owned)r.dispose()}};
}
